async function openModule(moduleId,entryMode="frontend"){
  const module=getModule(moduleId);
  if(!supportsAppSurface(module,entryMode))return;
  if(module.availability==="deployment-pending"){showToast(module.availabilityMessage||"此 App 的獨立部署尚未提供。請稍後再試。");return}
  const destination=module.entryModes[entryMode];
  if(destination){try{const lifecycle=AVALifecycle.moduleState(module.id);sessionStorage.setItem("ava:platform:module-launch",JSON.stringify({moduleId:module.id,requiredCloudInitialization:!lifecycle.initialized,cloudVersion:lifecycle.cloudVersion,launchedAt:new Date().toISOString()}));console.info(`[AVA] Opening ${module.name.split(" · ")[0]} mode=${entryMode}`);console.info(`[AVA] Module lifecycle: ${lifecycle.initialized?"local-first":"cloud-init-required"}`)}catch(error){console.warn("[AVA] Module launch metadata unavailable; continuing navigation",error)}preserveAvaReturnSurface(entryMode);if(entryMode==="admin"){try{await prepareIndependentAppLaunch(destination);if(module.adminLaunchContract==="ava-legacy-app-grant-v1")await AVAAdminAuth.launchLegacyAdminApp(module.id,destination);else await AVAAdminAuth.launchAdminApp(module.id,destination); }catch(error){showToast(`Admin launch denied：${error.message}`)}return}await prepareIndependentAppLaunch(destination);window.location.assign(destination);return}
  showToast("此 Module 尚未提供此入口");
}

async function prepareIndependentAppLaunch(destination){
  if(typeof navigator==="undefined"||!navigator.serviceWorker)return;
  let target;
  try{target=new URL(destination,window.location.href)}catch(_){return}
  if(target.origin!==window.location.origin)return;
  try{
    const registration=await navigator.serviceWorker.getRegistration(target.pathname);
    if(!registration)return;
    const platformScope=new URL("./",window.location.href).pathname;
    const registrationScope=new URL(registration.scope).pathname;
    const workerScript=registration.active?.scriptURL||registration.waiting?.scriptURL||registration.installing?.scriptURL||"";
    const workerScriptPath=workerScript?new URL(workerScript).pathname:"";
    if(registrationScope===platformScope||workerScriptPath.startsWith(platformScope)||(!workerScript&&registrationScope==="/")||!target.pathname.startsWith(registrationScope))return;
    await registration.update();
  }catch(error){console.warn("[AVA] Independent App service worker update check failed; continuing launch:",error)}
}

function preserveAvaReturnSurface(entryMode){
  const url=new URL(window.location.href);
  if(entryMode==="user"||entryMode==="admin")url.searchParams.set("avaSurface",entryMode);
  else url.searchParams.delete("avaSurface");
  history.replaceState(null,"",url.pathname+(url.search||"")+(url.hash||""));
}
